const first = $input.all()[0].json;
if (first.body && first.body.light_voltage !== undefined) {
  return [{ json: { ...first.body, timestamp: first.body.timestamp || new Date().toISOString(), source: 'esp32' } }];
}
const r = (a, b) => a + Math.random() * (b - a);
const list = ['normal','normal','normal','normal','low_voltage','high_voltage','interruption','overcurrent','overheating','gas_leak'];
const scen = list[Math.floor(Math.random() * list.length)];
const d = { light_voltage: r(226, 232), fan_voltage: r(227, 233), temperature_c: r(32, 37), gas_ppm: r(20, 60), current_a: r(2.5, 4.5) };
if (scen === 'low_voltage') d.light_voltage = r(180, 200);
if (scen === 'high_voltage') d.fan_voltage = r(256, 268);
if (scen === 'interruption') { d.light_voltage = r(0, 10); d.fan_voltage = r(0, 10); d.current_a = 0; }
if (scen === 'overcurrent') d.current_a = r(11, 16);
if (scen === 'overheating') d.temperature_c = r(62, 75);
if (scen === 'gas_leak') d.gas_ppm = r(350, 800);
Object.keys(d).forEach(k => { d[k] = +d[k].toFixed(1); });
return [{ json: { ...d, timestamp: new Date().toISOString(), source: 'simulator', simulated_scenario: scen } }];

const sd = $getWorkflowStaticData('global');
sd.history = sd.history || [];
sd.events = sd.events || [];
const d = $input.first().json;
const prev = sd.history[sd.history.length - 1];
const faults = [];
const add = (type, sev, detail) => faults.push({ type, severity: sev, detail });
const LOW = 207, HIGH = 253;
[['Light', d.light_voltage], ['Fan', d.fan_voltage]].forEach(([n, v]) => {
  if (v < 50) add('POWER_INTERRUPTION', 'critical', n + ' voltage collapsed to ' + v + ' V');
  else if (v < LOW) add('LOW_VOLTAGE', 'medium', n + ' voltage ' + v + ' V is below ' + LOW + ' V');
  else if (v > HIGH) add('HIGH_VOLTAGE', 'medium', n + ' voltage ' + v + ' V is above ' + HIGH + ' V');
});
if (prev) {
  ['light_voltage', 'fan_voltage'].forEach(k => {
    const delta = Math.abs(d[k] - prev[k]);
    if (delta > 30 && d[k] >= 50 && prev[k] >= 50) add('POWER_DISTURBANCE', 'medium', k + ' changed by ' + delta.toFixed(1) + ' V in one interval');
  });
}
if (d.current_a > 10) add('ABNORMAL_CURRENT', 'high', 'Load current ' + d.current_a + ' A exceeds 10 A limit');
if (d.temperature_c > 60) add('HIGH_TEMPERATURE', 'critical', 'Temperature ' + d.temperature_c + ' C exceeds 60 C');
else if (d.temperature_c > 45) add('HIGH_TEMPERATURE', 'high', 'Temperature ' + d.temperature_c + ' C exceeds 45 C');
if (d.gas_ppm > 600) add('GAS_LEAK', 'critical', 'Gas level ' + d.gas_ppm + ' ppm exceeds 600 ppm');
else if (d.gas_ppm > 300) add('GAS_LEAK', 'high', 'Gas level ' + d.gas_ppm + ' ppm exceeds 300 ppm');
const rank = { medium: 1, high: 2, critical: 3 };
let top = faults.reduce((m, f) => Math.max(m, rank[f.severity]), 0);
if (faults.length >= 2 && top < 3) top += 1;
const severity = ['normal', 'medium', 'high', 'critical'][top];
const power_kw = +(d.fan_voltage * d.current_a * 0.9 / 1000).toFixed(3);
sd.history.push({ ts: d.timestamp, light_voltage: d.light_voltage, fan_voltage: d.fan_voltage, temperature_c: d.temperature_c, gas_ppm: d.gas_ppm, current_a: d.current_a, power_kw, faults: faults.map(f => f.type) });
if (sd.history.length > 120) sd.history.shift();
const h = sd.history;
let run = 0;
for (let i = h.length - 1; i >= 0; i--) { if (h[i].current_a > 0.5) run++; else break; }
const total = h.reduce((s, x) => s + x.power_kw, 0);
sd.energy = { samples: h.length, avg_power_kw: +(total / h.length).toFixed(3), peak_power_kw: +Math.max(...h.map(x => x.power_kw)).toFixed(3), energy_kwh_window: +(total / 60).toFixed(3), continuous_run_minutes: run, note: run >= 60 ? 'Load has run continuously for over an hour' : '' };
if (faults.length) { sd.events.push({ ts: d.timestamp, severity, faults: faults.map(f => f.type) }); if (sd.events.length > 50) sd.events.shift(); }
return [{ json: { ...d, power_kw, faults, fault_count: faults.length, severity, abnormal: faults.length > 0 ? 'yes' : 'no', status: faults.length > 0 ? 'FAULT' : 'NORMAL', energy: sd.energy } }];

