const src = $('Edge Processing and Fault Detection').first().json;
const raw = String($input.first().json.output || '');
let a;
try {
  a = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  a = { severity: src.severity, fault_type: src.faults.map(f => f.type).join(', '), probable_causes: [], explanation: raw, recommendations: [], safety_action: '', energy_tip: '' };
}
const list = x => Array.isArray(x) ? x.map((t, i) => (i + 1) + '. ' + t).join('\n') : String(x || '');
const title = String(a.fault_type || 'FAULT').replace(/_/g, ' ').toUpperCase();
const message = 'ALERT [' + String(a.severity || src.severity).toUpperCase() + '] ' + title + ' DETECTED\n\n' +
  'Light Voltage: ' + src.light_voltage + ' V | Fan Voltage: ' + src.fan_voltage + ' V | Temperature: ' + src.temperature_c + ' C | Gas: ' + src.gas_ppm + ' ppm | Current: ' + src.current_a + ' A\n\n' +
  'Explanation: ' + a.explanation + '\n\n' +
  'Probable causes:\n' + list(a.probable_causes) + '\n\n' +
  'Recommended actions:\n' + list(a.recommendations) + '\n\n' +
  (a.safety_action ? 'Safety action: ' + a.safety_action + '\n\n' : '') +
  'Energy tip: ' + (a.energy_tip || 'None');
return [{ json: {
  timestamp: src.timestamp,
  severity: a.severity || src.severity,
  fault_type: a.fault_type,
  light_voltage: src.light_voltage,
  fan_voltage: src.fan_voltage,
  temperature_c: src.temperature_c,
  gas_ppm: src.gas_ppm,
  current_a: src.current_a,
  power_kw: src.power_kw,
  explanation: a.explanation,
  recommendations: Array.isArray(a.recommendations) ? a.recommendations.join('; ') : a.recommendations,
  energy_tip: a.energy_tip,
  alert_message: message
} }];

const sd = $getWorkflowStaticData('global');
const h = sd.history || [];
const latest = h.length ? h[h.length - 1] : null;
const chat = $input.first().json;
const context = {
  latest_reading: latest,
  system_status: latest ? (latest.faults.length ? 'FAULT: ' + latest.faults.join(', ') : 'NORMAL') : 'NO DATA YET',
  recent_fault_events: (sd.events || []).slice(-5),
  last_10_readings: h.slice(-10),
  energy_summary: sd.energy || null,
  thresholds: { voltage_v: '207 to 253', temperature_c: 'below 45', gas_ppm: 'below 300', current_a: 'below 10' }
};
return [{ json: { chatInput: chat.chatInput, sessionId: chat.sessionId, context: JSON.stringify(context) } }];
